from collections import Counter,deque

def comps(grid):
 h,w=len(grid),len(grid[0]); bg=Counter(x for r in grid for x in r).most_common(1)[0][0]
 seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   col=grid[r][c]
   if col==bg or (r,c) in seen: continue
   q=[(r,c)];seen.add((r,c)); cells=[]
   while q:
    x,y=q.pop();cells.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     xx,yy=x+dx,y+dy
     if 0<=xx<h and 0<=yy<w and (xx,yy) not in seen and grid[xx][yy]==col:
      seen.add((xx,yy));q.append((xx,yy))
   out.append((col,cells))
 return bg,out
